from dataclasses import dataclass

@dataclass
class Call:
    model: str
    tokens_in: int
    tokens_out: int

    def cost(self, price_in=0.4, price_out=1.6):
        return (self.tokens_in * price_in + self.tokens_out * price_out) / 1_000_000

call = Call('mini', 1000, 500)
print(call.model, round(call.cost(), 6))

# Sirf plain functions - koi library nahi.
def loss(w):
    return (w - 3.0) ** 2

def grad(w):
    return 2.0 * (w - 3.0)

def descend(lr, w=-4.0, steps=6):
    path = [round(w, 2)]
    for _ in range(steps):
        w = w - lr * grad(w)      # ulti direction mein chhota step
        path.append(round(w, 2))
    return path

print("lr=0.1 :", descend(0.1), "-> 3 ki taraf badhta hai")
print("lr=0.9 :", descend(0.9), "-> oscillate karke aata hai")
print("lr=1.1 :", descend(1.1), "-> diverge, loss badhta hai")

