rows = [
    {'city': 'Pune', 'amount': 200},
    {'city': 'Pune', 'amount': 400},
    {'city': 'Delhi', 'amount': 300},
]

def mean_by_group(rows, key, value):
    totals, counts = {}, {}
    for row in rows:
        name = row[key]
        totals[name] = totals.get(name, 0) + row[value]
        counts[name] = counts.get(name, 0) + 1
    return {name: totals[name] / counts[name] for name in totals}

means = mean_by_group(rows, 'city', 'amount')
print(means)

