exercises.solution:
users = [{'id': 1, 'name': 'Asha'}, {'id': 2, 'name': 'Ravi'}]
orders = [
    {'user_id': 1, 'total': 250},
    {'user_id': 1, 'total': 150},
    {'user_id': 3, 'total': 99},
]

def spend_by_user(users, orders):
    spend = {user['id']: 0 for user in users}
    for order in orders:
        if order['user_id'] in spend:
            spend[order['user_id']] += order['total']
    return {user['name']: spend[user['id']] for user in users}

result = spend_by_user(users, orders)
print(result)
